const Preview: React.FC<{ item: ModaoItem }> = ({ item }) => {
  const previewRef = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);
  const [scale, setScale] = useState(0.5);
  const data = useMemo(() => createOfficialComponentData(item), [item]);

  useEffect(() => {
    const target = previewRef.current;
    if (!target) return;
    const updateScale = () => {
      const bounds = target.getBoundingClientRect();
      if (bounds.width > 0 && bounds.height > 0) setScale(Math.min(bounds.width / 280, bounds.height / 180));
    };
    let resizeObserver: ResizeObserver | undefined;
    const intersectionObserver = typeof IntersectionObserver === 'undefined'
      ? undefined
      : new IntersectionObserver(([entry]) => {
        if (!entry.isIntersecting) return;
        setVisible(true);
        updateScale();
        resizeObserver = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(updateScale);
        resizeObserver?.observe(target);
        intersectionObserver?.disconnect();
      }, { rootMargin: '180px' });
    if (intersectionObserver) intersectionObserver.observe(target);
    else { updateScale(); setVisible(true); }
    return () => { intersectionObserver?.disconnect(); resizeObserver?.disconnect(); };
  }, []);

  return <div ref={previewRef} className="official-native-preview" aria-hidden="true" style={{ display: 'grid', placeItems: 'center', width: '100%', height: '100%', overflow: 'hidden', pointerEvents: 'none' }}>
    {visible && <div style={{ width: 280, height: 180, transform: `scale(${scale})`, transformOrigin: 'center', flex: '0 0 auto' }}><OfficialModaoRenderer data={data} interactive={false} /></div>}
  </div>;
};

const ComponentTile: React.FC<{ item: ModaoItem; selected: boolean; onSelect: () => void; onInsert: () => void }> = ({ item, selected, onSelect, onInsert }) => {
  const [favorite, setFavorite] = useState(false);
  useEffect(() => { try { const raw = localStorage.getItem('aether-official-component-favorites'); const values: unknown = raw ? JSON.parse(raw) : []; setFavorite(Array.isArray(values) && values.includes(`component:${item.id}`)); } catch { setFavorite(false); } }, [item.id]);
  const toggle = (event: React.MouseEvent) => { event.stopPropagation(); try { const raw = localStorage.getItem('aether-official-component-favorites'); const values: unknown = raw ? JSON.parse(raw) : []; const current = Array.isArray(values) ? values.filter((value): value is string => typeof value === 'string') : []; const next = current.includes(`component:${item.id}`) ? current.filter((value) => value !== `component:${item.id}`) : [`component:${item.id}`, ...current]; localStorage.setItem('aether-official-component-favorites', JSON.stringify(next)); setFavorite(next.includes(`component:${item.id}`)); window.dispatchEvent(new Event('aether-official-component-favorites-changed')); } catch { /* storage unavailable */ } };
  return <div role="button" aria-pressed={selected} tabIndex={0} className={`official-component-tile ${selected ? 'is-selected' : ''}`} onClick={onSelect} onDoubleClick={onInsert} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onSelect(); } }} aria-label={`选择${item.label}`} title="单击选择，双击插入画布"><div className="official-tile-preview"><Preview item={item} /><button type="button" className={`official-favorite-button ${favorite ? 'is-favorite' : ''}`} aria-label={favorite ? `取消收藏 ${item.label}` : `收藏 ${item.label}`} aria-pressed={favorite} title={favorite ? '取消收藏' : '收藏'} onClick={toggle} onDoubleClick={(event) => event.stopPropagation()}><Heart size={13} fill={favorite ? 'currentColor' : 'none'} /></button>{item.premium && <span className="official-premium"><Crown size={11} />会员</span>}{selected && <span className="official-tile-check"><Check size={11} /></span>}</div><span className="official-tile-name">{item.label}</span></div>;
};

